mapper.sql:
WITH RECURSIVE korea_regions AS ( SELECT id FROM country_categories WHERE id = #{koreaRootId}
UNION ALL
SELECT child.id FROM country_categories child JOIN korea_regions parent ON child.parent_id = parent.id )

mapper.select:
SELECT bookmarked_content.targetId, bookmarked_content.boardType, bookmarked_content.postType, bookmarked_content.title, bookmarked_content.nickname, bookmarked_content.writerWithdrawn, bookmarked_content.createdAt, bookmarked_content.views, bookmarked_content.bookmarkCreatedAt FROM (
) bookmarked_content WHERE 1 = 1
ORDER BY bookmarked_content.bookmarkCreatedAt DESC, bookmarked_content.bookmarkId DESC LIMIT #{limit} OFFSET #{offset}
